-- Roster Master Web App / Batch 2.1 / PostgreSQL 15+
-- Run on a NEW empty database. Never run against the legacy application data.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE DOMAIN fte_amount AS numeric(10,4) CHECK (VALUE >= 0);
CREATE TABLE company_groups(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), group_code text NOT NULL UNIQUE, group_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_group_id uuid REFERENCES company_groups(id), company_code text NOT NULL UNIQUE, company_name text NOT NULL, legal_name text, tax_id text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')));
CREATE TABLE divisions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL REFERENCES companies(id), division_code text NOT NULL, division_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), UNIQUE(company_id,division_code), UNIQUE(id,company_id));
CREATE TABLE sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), division_id uuid NOT NULL REFERENCES divisions(id), section_code text NOT NULL, section_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), UNIQUE(division_id,section_code), UNIQUE(id,division_id));
CREATE TABLE departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), division_id uuid NOT NULL REFERENCES divisions(id), section_id uuid, department_code text NOT NULL UNIQUE, department_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), FOREIGN KEY(section_id,division_id) REFERENCES sections(id,division_id), UNIQUE(id,division_id));
CREATE TABLE employment_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), type_code text NOT NULL UNIQUE, type_name text NOT NULL, status text NOT NULL DEFAULT 'active');
CREATE TABLE nationalities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), nationality_code text NOT NULL UNIQUE, nationality_name text NOT NULL, status text NOT NULL DEFAULT 'active');
CREATE TABLE education_levels(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), education_code text NOT NULL UNIQUE, education_name text NOT NULL, sort_order int NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'active');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), auth_user_id uuid UNIQUE, username text NOT NULL UNIQUE, email text UNIQUE, display_name text NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','disabled')), last_login_at timestamptz);
CREATE TABLE employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_code text NOT NULL UNIQUE, full_name text NOT NULL, nickname text, employment_type_id uuid REFERENCES employment_types(id), home_company_id uuid NOT NULL REFERENCES companies(id), hire_date date, probation_end_date date, termination_date date, termination_reason text, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), row_version int NOT NULL DEFAULT 1 CHECK(row_version > 0));
ALTER TABLE users ADD COLUMN employee_id uuid UNIQUE REFERENCES employees(id);
CREATE TABLE employee_profiles(employee_id uuid PRIMARY KEY REFERENCES employees(id), prefix text, gender text, birth_date date, national_id_encrypted bytea, national_id_lookup_hash bytea UNIQUE, nationality_id uuid REFERENCES nationalities(id), education_level_id uuid REFERENCES education_levels(id), phone text, email text, address text, emergency_contact_name text, emergency_contact_phone text);
CREATE TABLE positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_code text NOT NULL UNIQUE, position_name text NOT NULL, department_id uuid NOT NULL REFERENCES departments(id), employment_type_id uuid REFERENCES employment_types(id), grade smallint CHECK(grade BETWEEN 1 AND 8), target_fte fte_amount NOT NULL DEFAULT 1, parent_position_id uuid REFERENCES positions(id), org_order int, org_offset numeric(10,2), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), row_version int NOT NULL DEFAULT 1 CHECK(row_version>0), CHECK(parent_position_id IS DISTINCT FROM id));
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role_code text NOT NULL UNIQUE, role_name text NOT NULL, description text, status text NOT NULL DEFAULT 'active');
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), permission_code text NOT NULL UNIQUE, resource text NOT NULL, action text NOT NULL, description text);
CREATE TABLE role_permissions(role_id uuid NOT NULL REFERENCES roles(id), permission_id uuid NOT NULL REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
-- A scope row has exactly one target; central is global. No polymorphic FK.
CREATE TABLE user_role_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), role_id uuid NOT NULL REFERENCES roles(id), scope_type text NOT NULL CHECK(scope_type IN ('central','company','division','department')), company_id uuid REFERENCES companies(id), division_id uuid REFERENCES divisions(id), department_id uuid REFERENCES departments(id), valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), CHECK(valid_to IS NULL OR valid_to>valid_from), CHECK((scope_type='central' AND company_id IS NULL AND division_id IS NULL AND department_id IS NULL) OR (scope_type='company' AND company_id IS NOT NULL AND division_id IS NULL AND department_id IS NULL) OR (scope_type='division' AND company_id IS NULL AND division_id IS NOT NULL AND department_id IS NULL) OR (scope_type='department' AND company_id IS NULL AND division_id IS NULL AND department_id IS NOT NULL)));
CREATE TABLE request_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_type_code text NOT NULL UNIQUE, request_type_name text NOT NULL, target_entity text NOT NULL, requires_attachment boolean NOT NULL DEFAULT false, requires_approval boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'active');
CREATE TABLE approval_workflows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_type_id uuid NOT NULL REFERENCES request_types(id), workflow_name text NOT NULL, workflow_version int NOT NULL CHECK(workflow_version>0), company_id uuid REFERENCES companies(id), effective_from date NOT NULL, effective_to date, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','active','retired')), CHECK(effective_to IS NULL OR effective_to>=effective_from), UNIQUE(id,request_type_id));
CREATE TABLE approval_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workflow_id uuid NOT NULL REFERENCES approval_workflows(id), step_order int NOT NULL CHECK(step_order>0), step_name text NOT NULL, approver_role_id uuid REFERENCES roles(id), approver_user_id uuid REFERENCES users(id), approval_scope text NOT NULL CHECK(approval_scope IN ('company','central','related_company')), required_approvals int NOT NULL DEFAULT 1 CHECK(required_approvals>0), allow_self_approval boolean NOT NULL DEFAULT false, UNIQUE(workflow_id,step_order), CHECK(approver_role_id IS NOT NULL OR approver_user_id IS NOT NULL), UNIQUE(id,workflow_id));
CREATE TABLE change_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_no text NOT NULL UNIQUE, request_type_id uuid NOT NULL REFERENCES request_types(id), workflow_id uuid NOT NULL, requester_id uuid NOT NULL REFERENCES users(id), company_id uuid NOT NULL REFERENCES companies(id), target_company_id uuid REFERENCES companies(id), title text NOT NULL, reason text, status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending_review','pending_approval','returned','approved','rejected','cancelled','applied')), current_step_order int, submitted_at timestamptz, completed_at timestamptz, effective_date date, row_version int NOT NULL DEFAULT 1 CHECK(row_version>0), FOREIGN KEY(workflow_id,request_type_id) REFERENCES approval_workflows(id,request_type_id), UNIQUE(id,workflow_id));
CREATE TABLE request_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES change_requests(id), entity_type text NOT NULL, entity_id uuid, operation text NOT NULL CHECK(operation IN ('create','update','deactivate')), before_data jsonb, proposed_data jsonb NOT NULL, expected_row_version int, CHECK((operation='create' AND entity_id IS NULL) OR (operation<>'create' AND entity_id IS NOT NULL AND expected_row_version IS NOT NULL)));
CREATE TABLE request_approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES change_requests(id), approval_step_id uuid NOT NULL REFERENCES approval_steps(id), approver_id uuid NOT NULL REFERENCES users(id), review_round int NOT NULL DEFAULT 1 CHECK(review_round>0), decision text NOT NULL CHECK(decision IN ('approved','rejected','returned')), comment text, decided_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_id,approval_step_id,approver_id,review_round));
CREATE TABLE request_attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES change_requests(id), file_name text NOT NULL, storage_key text NOT NULL UNIQUE, mime_type text NOT NULL, file_size bigint NOT NULL CHECK(file_size>=0), checksum_sha256 char(64) NOT NULL, uploaded_by uuid NOT NULL REFERENCES users(id), uploaded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE employee_company_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES employees(id), company_id uuid NOT NULL REFERENCES companies(id), effective_from date NOT NULL, effective_to date, source_request_id uuid REFERENCES change_requests(id), CHECK(effective_to IS NULL OR effective_to>=effective_from), EXCLUDE USING gist(employee_id WITH =, daterange(effective_from,COALESCE(effective_to+1,'infinity'::date),'[)') WITH &&));
CREATE TABLE employee_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employee_id uuid NOT NULL REFERENCES employees(id), position_id uuid NOT NULL REFERENCES positions(id), assignment_type text NOT NULL CHECK(assignment_type IN ('primary','secondary')), assignment_fte fte_amount NOT NULL CHECK(assignment_fte>0), effective_from date NOT NULL, effective_to date, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','ended','cancelled')), source_request_id uuid REFERENCES change_requests(id), CHECK(effective_to IS NULL OR effective_to>=effective_from));
ALTER TABLE employee_assignments ADD CONSTRAINT no_overlapping_primary EXCLUDE USING gist(employee_id WITH =, daterange(effective_from,COALESCE(effective_to+1,'infinity'::date),'[)') WITH &&) WHERE (assignment_type='primary' AND status<>'cancelled');
CREATE TABLE position_fte_history(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), position_id uuid NOT NULL REFERENCES positions(id), target_fte fte_amount NOT NULL, effective_from date NOT NULL, effective_to date, source_request_id uuid REFERENCES change_requests(id), approved_at timestamptz, CHECK(effective_to IS NULL OR effective_to>=effective_from), EXCLUDE USING gist(position_id WITH =, daterange(effective_from,COALESCE(effective_to+1,'infinity'::date),'[)') WITH &&));
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_user_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id uuid, company_id uuid REFERENCES companies(id), request_id uuid REFERENCES change_requests(id), changed_fields jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE migration_batches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_version text, source_checksum char(64) NOT NULL, source_file_name text NOT NULL, imported_by uuid REFERENCES users(id), imported_at timestamptz, status text NOT NULL DEFAULT 'staged', total_records int, success_records int, error_records int, UNIQUE(source_checksum));
CREATE TABLE legacy_id_mappings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), migration_batch_id uuid NOT NULL REFERENCES migration_batches(id), entity_type text NOT NULL, legacy_id text NOT NULL, legacy_scope text NOT NULL DEFAULT '', new_id uuid NOT NULL, mapping_status text NOT NULL CHECK(mapping_status IN ('matched','created','unresolved')), UNIQUE(migration_batch_id,entity_type,legacy_scope,legacy_id));
CREATE TABLE migration_issues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), migration_batch_id uuid NOT NULL REFERENCES migration_batches(id), entity_type text NOT NULL, source_record_key text, issue_code text NOT NULL, issue_detail text NOT NULL, source_data jsonb, resolution_status text NOT NULL DEFAULT 'unresolved' CHECK(resolution_status IN ('unresolved','resolved','excluded')), resolved_by uuid REFERENCES users(id), resolved_at timestamptz);
CREATE INDEX idx_employees_company ON employees(home_company_id);
CREATE INDEX idx_positions_department ON positions(department_id);
CREATE INDEX idx_assignments_employee_dates ON employee_assignments(employee_id,effective_from,effective_to);
CREATE INDEX idx_requests_company_status ON change_requests(company_id,status);
CREATE INDEX idx_roles_user ON user_role_assignments(user_id,status);
CREATE INDEX idx_migration_issues_batch ON migration_issues(migration_batch_id,resolution_status);
COMMIT;